### 3. ESP32 का कोड (Arduino IDE)

कोड अपलोड करने से पहले Arduino IDE के Library Manager से **`RTClib`** (by Adafruit) इंस्टॉल कर लें।

```cpp
#include <Wire.h>
#include <RTClib.h>

RTC_DS3231 rtc;

// ---------- पिन कॉन्फ़िगरेशन ----------
const int PIN_FENCE_RELAY = 26;
const int PIN_LIGHT_RELAY = 27;
const int PIN_SIREN_RELAY = 25;
const int PIN_PIR         = 34;

// ज़्यादातर Optocoupler Relay मॉड्यूल LOW सिग्नल पर ON होते हैं
const bool RELAY_ACTIVE_LOW = true;

// ---------- टाइम और अलार्म सेटिंग्स ----------
const int NIGHT_START_HOUR = 18;  // शाम 6 बजे फेंस ON
const int NIGHT_END_HOUR   = 6;   // सुबह 6 बजे फेंस OFF

// बकरियों को क्रॉनिक स्ट्रेस से बचाने और तेंदुए को आदी (habituate) होने से रोकने की सेटिंग्स:
const unsigned long LIGHT_DURATION_MS = 60000; // फ्लडलाइट पूरे 60 सेकंड जलेगी (जैसा आपने चाहा)
const unsigned long SIREN_MAX_MS      = 15000; // सायरन सिर्फ शुरुआती 15 सेकंड बजेगा ताकि शेड में बकरियां पैनिक न करें (चाहें तो 60000 कर सकते हैं)
const unsigned long MOTION_CONFIRM_MS = 1500;  // 1.5 सेकंड लगातार/दोबारा हलचल हो तभी अलार्म बजे (हवा या पक्षी से फॉल्स अलार्म रोकने के लिए)
const unsigned long COOLDOWN_MS       = 8000;  // एक अलार्म खत्म होने के बाद 8 सेकंड का शांत गैप
const unsigned long PIR_WARMUP_MS     = 60000; // बूट होने पर PIR सेंसर को 1 मिनट सेटल होने का समय

// अनियमित (Irregular) सायरन पैटर्न ताकि तेंदुआ एक जैसी आवाज़ का आदी न हो
const unsigned long SIREN_PATTERN[] = {1200, 400, 800, 600, 1500, 500}; 
const int PATTERN_STEPS = 6;

// ---------- सिस्टम स्टेट वेरिएबल्स ----------
bool alarmActive = false;
unsigned long alarmStart = 0;
unsigned long alarmEnd = 0;
unsigned long motionFirstSeen = 0;
bool confirmingMotion = false;
bool rtcOk = true;

void setRelay(int pin, bool turnOn) {
  digitalWrite(pin, (turnOn ^ RELAY_ACTIVE_LOW) ? HIGH : LOW);
}

bool isNightTime() {
  if (!rtcOk) return true; // अगर RTC खराब हो तो सुरक्षा के लिए रात मानकर चलें
  DateTime now = rtc.now();
  int h = now.hour();
  return (h >= NIGHT_START_HOUR || h < NIGHT_END_HOUR);
}

void setup() {
  Serial.begin(115200);

  pinMode(PIN_FENCE_RELAY, OUTPUT);
  pinMode(PIN_LIGHT_RELAY, OUTPUT);
  pinMode(PIN_SIREN_RELAY, OUTPUT);
  pinMode(PIN_PIR, INPUT);

  // शुरुआत में सारे रिले OFF रखें
  setRelay(PIN_FENCE_RELAY, false);
  setRelay(PIN_LIGHT_RELAY, false);
  setRelay(PIN_SIREN_RELAY, false);

  Wire.begin(21, 22);
  if (!rtc.begin()) {
    Serial.println("RTC नहीं मिला! सुरक्षा के लिए सिस्टम नाइट मोड में चलेगा।");
    rtcOk = false;
  } else if (rtc.lostPower()) {
    Serial.println("RTC का टाइम कंप्यूटर के टाइम से सिंक किया जा रहा है...");
    rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
  }
}

void loop() {
  unsigned long nowMs = millis();
  bool night = isNightTime();

  // 1. शाम 6 से सुबह 6 तक सोलर फेंस एनर्जाइज़र ON रखें
  setRelay(PIN_FENCE_RELAY, night);

  // 2. PIR मोशन डिटेक्शन (फॉल्स-अलार्म फिल्टर के साथ)
  bool warmedUp = (nowMs > PIR_WARMUP_MS);
  bool motion = (digitalRead(PIN_PIR) == HIGH);

  if (night && warmedUp && !alarmActive && (nowMs - alarmEnd > COOLDOWN_MS)) {
    if (motion) {
      if (!confirmingMotion) {
        confirmingMotion = true;
        motionFirstSeen = nowMs;
      } else if (nowMs - motionFirstSeen >= MOTION_CONFIRM_MS) {
        // हलचल कन्फर्म हो गई (पक्षी या हवा का झोंका नहीं है) -> अलार्म चालू करें
        alarmActive = true;
        alarmStart = nowMs;
        confirmingMotion = false;
        Serial.println("कन्फर्म मोशन! लाइट और सायरन ON");
      }
    } else {
      confirmingMotion = false;
    }
  }

  // 3. अलार्म और लाइट कंट्रोल
  if (alarmActive) {
    unsigned long elapsed = nowMs - alarmStart;

    // फ्लडलाइट पूरे 60 सेकंड चालू रहेगी
    setRelay(PIN_LIGHT_RELAY, true);

    // सायरन सिर्फ SIREN_MAX_MS (15 सेकंड) तक अनियमित पल्स में बजेगा
    if (elapsed < SIREN_MAX_MS) {
      unsigned long cycleTime = elapsed % 5000;
      unsigned long acc = 0;
      bool sirenState = false;
      for (int i = 0; i < PATTERN_STEPS; i++) {
        acc += SIREN_PATTERN[i];
        if (cycleTime < acc) {
          sirenState = (i % 2 == 0); // सम (even) स्टेप पर ON, विषम (odd) पर OFF
          break;
        }
      }
      setRelay(PIN_SIREN_RELAY, sirenState);
    } else {
      setRelay(PIN_SIREN_RELAY, false); // 15 सेकंड बाद सायरन बंद, लाइट जलती रहेगी
    }

    // 60 सेकंड पूरे होने पर सब बंद करें
    if (elapsed >= LIGHT_DURATION_MS) {
      alarmActive = false;
      alarmEnd = nowMs;
      setRelay(PIN_LIGHT_RELAY, false);
      setRelay(PIN_SIREN_RELAY, false);
      Serial.println("60 सेकंड पूरे, अलार्म OFF");
    }
  } else {
    setRelay(PIN_LIGHT_RELAY, false);
    setRelay(PIN_SIREN_RELAY, false);
  }

  delay(50);
}
```

